style.css:
body {
    margin: 0;
    height: 100vh;
    overflow: hidden;
    background: linear-gradient(45deg, #000, #333, #000);
    background-size: 300% 300%;
    animation: gradient 5s ease infinite;
}

@keyframes gradient {
    0% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0% 50%;
    }
}
